export const skinCoreTerms: TermInput[] = [
  { id: "keratinocyte-cancer", kind: "term", asOf, name: "Keratinocyte cancer (and why 'non-melanoma skin cancer' is being retired)", category: "Pathology", wikipedia: W("Skin_cancer"),
    aka: ["keratinocyte cancer", "keratinocyte carcinoma", "KC", "keratinocyte skin cancer", "non-melanoma skin cancer", "NMSC", "non melanoma skin cancer", "keratinocyte-derived skin cancer", "C44", "ICD-10 C44"],
    tldr: "The two commonest cancers in the world, basal cell carcinoma and cutaneous squamous cell carcinoma, both arise from keratinocytes, the cells that make up most of the outer layer of skin. They used to be lumped together as non-melanoma skin cancer, a name defined by what they are not; dermatologists have agreed to call them keratinocyte cancers instead.",
    summary: "Basal cell carcinoma and cutaneous squamous cell carcinoma are about 75 percent and 25 percent respectively of the group (Cancer Research UK). Both come from keratinocytes in the epidermis, both are overwhelmingly caused by ultraviolet light, both occur mostly on the head, neck, forearms and hands, and both are cured in the great majority of people by removing them. Melanoma comes from a different cell, the melanocyte, behaves differently and is on its own pages here.\n\nThe old name, non-melanoma skin cancer, has two faults. It defines a group by what it is not, and it quietly includes things that are not keratinocyte cancers at all: the ICD-10 code it is usually read as, C44, is a site code covering all malignant neoplasms of skin other than melanoma, so Merkel cell carcinoma and the adnexal carcinomas fall inside it too, and mortality figures published for 'non-melanoma skin cancer' may include them. A European consensus group of dermato-oncologists voted unanimously in 2024 for the consistent use of keratinocyte cancer instead, on the ground that it is more precise and correct by cause, and that this should help patients and doctors understand each other (Philipp-Dormston 2024). Their definition of the group includes the precursors, actinic keratosis and Bowen's disease, as keratinocyte-derived.\n\nThe practical consequence for anybody reading statistics is that the two names do not cover quite the same thing, and that C44 is a site code rather than a diagnosis: basal cell carcinoma and squamous cell carcinoma are told apart only by the morphology code the pathologist adds, not by the ICD-10 code. This matters more than it sounds, because it is one of the reasons the counting is as difficult as it is.",
    cancers: ["skin-cancer", "basal-cell-carcinoma", "cutaneous-scc", "bowens-disease", "merkel-cell-carcinoma"],
    terms: ["keratinocyte-cancer-counting", "actinic-keratosis", "keratoacanthoma", "squamous-cell-carcinoma"],
    related: ["squamous-cell-carcinoma", "carcinoma", "field-cancerisation"],
    sections: ["diagnostics"],
    links: [SRC.kcConsensus, SRC.crukTypes, SRC.icd10, SRC.getDataOut, SRC.kwiatkowska2021],
  },

  { id: "keratinocyte-cancer-counting", kind: "term", asOf, name: "Why nobody knows how many skin cancers there are: the counting rule behind every figure", category: "Epidemiology & prevention", wikipedia: W("Cancer_registry"),
    aka: ["skin cancer under-registration", "non-melanoma skin cancer registration", "NMSC under-registration", "first per person per annum", "1st PPPA", "PPPA", "first tumour per patient", "UKIACR counting rule", "C44 excluded", "all cancers excluding non-melanoma skin cancer", "keratinocyte cancer incidence caveat", "skin cancer statistics caveat"],
    tldr: "Cancer registries were never built to count a cancer that people get several of. Britain's registries long recorded only the first basal cell carcinoma and the first squamous cell carcinoma in a person's lifetime, and the headline 'cancer in the UK' figure leaves these cancers out altogether. Every number on these pages is a floor, not a count.",
    summary: "The rule came first. In 1999 the UK and Ireland Association of Cancer Registries decided that, because of the difficulty of registering multiple pathology reports accurately, only the first basal cell carcinoma or squamous cell carcinoma per patient would be reported (quoted in Venables 2019). That is one registration per person per lifetime for each of the two types, whatever happens afterwards. Since people who get one keratinocyte cancer very often get several, the effect is large and one-directional.\n\nHow large has now been measured three times, each by comparing the old rule against counting the first of each type per person per year instead. Over England in 2013 to 2015, the annual method found 410,716 basal cell carcinomas against 268,565 on the old rule, 53 percent more, and 104,529 squamous cell carcinomas against 76,977, 36 percent more; 51 percent more keratinocyte cancers in all, and the authors judged that even this was still 5 to 11 percent short of the true tumour count (Venables 2019). Over 2013 to 2018 the gap was 59.2 percent for basal cell carcinoma and 37.2 percent for squamous cell carcinoma, and the residual shortfall was about 14 basal cell carcinomas and 2 squamous cell carcinomas per 100 patients (Kwiatkowska 2021). Over 2013 to 2022 it was 67 percent and 42 percent (Mistry 2026). The direction is always the same: the more carefully anybody counts, the more there turn out to be.\n\nThe four UK nations do not do the same thing, so their figures are not comparable with each other. England registers the first of each type per person and imputes the rest from pathology records, publishing on the annual basis. Scotland collects only the first occurrence of a basal cell carcinoma, in its own words 'because they are so common', but registers every squamous cell carcinoma manually (Public Health Scotland, September 2025; Venables 2019). Wales moved to the annual method from 2016 data and is the most explicit about it; on that basis non-melanoma skin cancer was 40 percent of all cancer cases in Wales in 2020, 11,792 first occurrences against 17,461 of every other cancer combined (Public Health Wales, May 2024). Northern Ireland publishes about 3,852 cases a year for 2018 to 2022.\n\nAnd then the whole group is taken out of the headline. The Office for National Statistics defines all cancers as ICD-10 C00 to C97 excluding C44, stating that it has been advised 'that non-melanoma skin cancer (NMSC) is greatly under-registered' and that the exclusion exists 'to ensure that the reported figures are meaningful'; its bulletins add that the available figures 'are known to be underestimates and unreliable for comparison purposes' because recording policies have varied between registries. So when a British source says there are just over 400,000 new cancers a year in the UK, the commonest cancer of all is not in that number: around 156,000 non-melanoma skin cancers are counted separately (Cancer Research UK), and the research estimate on the annual method is 234,861 a year across the UK for 2016 to 2018 (Kwiatkowska 2021).\n\nNone of this is a reason to distrust the figures. It is a reason to read them as the floor of a range. Two practical rules follow. A rising trend in these statistics may be a rising disease, a changing counting rule, or both, and a reader should check which is being compared. And a comparison between England and another country is very often a comparison of counting methods: the NDRS notes that English rates can look alarmingly high beside other countries' simply because other countries still count only the first tumour.",
    cancers: ["skin-cancer", "basal-cell-carcinoma", "cutaneous-scc", "bowens-disease", "merkel-cell-carcinoma", "melanoma"],
    terms: ["keratinocyte-cancer", "actinic-keratosis", "field-cancerisation"],
    related: ["cancer-registries-surveillance", "field-cancerisation", "incidence-vs-prevalence"],
    sections: ["diagnostics"],
    links: [SRC.venables2019, SRC.kwiatkowska2021, SRC.mistry2026, SRC.onsQmi, SRC.onsBulletin, SRC.phs, SRC.phw, SRC.crukIncidence, SRC.crukAllCancers, SRC.getDataOut],
    notes: [
      "The figures this term qualifies, with their methods named. On the lifetime-first method Cancer Research UK gives around 156,000 new non-melanoma skin cancers a year in the UK, against 403,601 of all other cancers combined, and 1,200 deaths a year. On the annual method the research estimate is 234,861 a year across the UK for 2016 to 2018, 184,280 basal cell and 50,582 squamous cell carcinomas (Kwiatkowska 2021). In England in 2022, age-standardised rates on the annual method were 295 per 100,000 person-years for basal cell carcinoma and 102 for squamous cell carcinoma (Mistry 2026). Registry counts in England for 2019 were 282.36 per 100,000 person-years for basal cell carcinoma and 85.24 for squamous cell carcinoma (van Bodegraven 2023).",
      "Why this is not simply a data-quality complaint. Under-registration has consequences a patient can feel. Services are commissioned on registered numbers; dermatology and Mohs capacity is planned on them; and a cancer that is officially rare enough to leave out of the national total competes badly for attention against cancers that are in it. The same registries that cannot count these tumours can count melanoma precisely, which is part of why melanoma has more research behind it.",
      "The coding system cannot see the distinction that decides treatment. Registries code morphology in ICD-O, and ICD-O gives micronodular basal cell carcinoma no code of its own, filing it as a related term under 8097/3 alongside nodular, which is a low-risk pattern; sclerosing and morphoeic share 8092/3 with infiltrating. So registry data can separate basal cell from squamous cell carcinoma but cannot reliably separate the high-risk growth patterns from the low-risk ones. Any statement about how many high-risk basal cell carcinomas there are in Britain therefore rests on reading reports rather than on counting codes.",
      "Mortality is counted differently again and is rising. Deaths are published for non-melanoma skin cancer as a single category, which may include rare tumours such as Merkel cell carcinoma as well as squamous cell carcinoma (Kwiatkowska 2021). In England that age-standardised mortality rate rose significantly from 2013, by about 4.0 percent a year, and roughly twice as fast in men as in women (Mistry 2026). A cancer group whose incidence is undercounted and whose mortality is rising is not the harmless thing the exclusion from the national total implies.",
    ],
  },

  { id: "bcc-growth-pattern", kind: "term", asOf, name: "The growth pattern on a basal cell carcinoma report: nodular, superficial, infiltrative, basosquamous", category: "Pathology", wikipedia: W("Basal-cell_carcinoma"),
    aka: ["nodular basal cell carcinoma", "superficial basal cell carcinoma", "infiltrative basal cell carcinoma", "infiltrating basal cell carcinoma", "morphoeic basal cell carcinoma", "sclerosing basal cell carcinoma", "micronodular basal cell carcinoma", "basosquamous carcinoma", "fibroepithelial basal cell carcinoma", "Pinkus tumour", "fibroepithelioma of Pinkus", "composite basal cell carcinoma", "pigmented basal cell carcinoma", "BCC subtype", "BCC growth pattern", "high-risk BCC"],
    tldr: "Basal cell carcinomas are sorted by the shape they grow in, and the shape decides how much skin has to be taken and who does it. Nodular and superficial patterns are low risk; infiltrating, sclerosing or morphoeic, and micronodular patterns are high risk because their edges are ragged and invisible. Most tumours contain more than one pattern, and the worst one present decides.",
    summary: "WHO names the subtypes and Britain sorts them. The fourth edition of the WHO skin classification (2018) listed ten: nodular, superficial, micronodular, infiltrating, sclerosing or morphoeic, basosquamous carcinoma, pigmented, with sarcomatoid differentiation, with adnexal differentiation, and fibroepithelial (of Pinkus). The fifth edition (2025) lists the same nine minus pigmented basal cell carcinoma, which no longer has a heading of its own and survives as a related term under the general ICD-O code. The UK reporting dataset uses the WHO classification and divides growth pattern into low and high biological risk (RCPath G123).\n\nThe low-risk patterns. **Superficial** basal cell carcinoma is made of multiple small collections of follicular germ cells in contact with the epidermis or hair follicles, most widely defined as not extending beyond the papillary dermis, and all published thickness definitions are under 1 mm; it is often called multicentric or multifocal, which the dataset calls a misnomer since the apparently separate islands are usually continuous. It is often accompanied by a stromal reaction in the upper dermis that may be the only abnormality visible in a small biopsy. The dataset notes that there is no consensus on whether superficial basal cell carcinoma is in situ or invasive, which is why its title avoids the phrase invasive basal cell carcinoma altogether. **Nodular** basal cell carcinoma grows as nodules of varying size, sometimes cystic or with keratin cysts, larger than the micronodules below; it is the commonest pattern. **Fibroepithelial** basal cell carcinoma (of Pinkus) is contested, with a long argument over whether it is a basal cell carcinoma or a benign trichoblastoma; WHO and therefore the UK dataset treat it as low risk.\n\nThe high-risk patterns. **Infiltrating** basal cell carcinoma grows as irregular islands and strands with a jagged or spiky outline. **Sclerosing or morphoeic** is that same infiltrating pattern with dense stromal fibrosis around it, which is what makes a morphoeic tumour feel like a scar and makes its edge impossible to see. **Micronodular** grows as small round nodules of follicular bulb size, defined as under 0.15 mm across, roughly fewer than 25 cells wide; the dataset asks that the term be kept for tumours that also infiltrate at the edge. All three are reported together in the UK as **infiltrative basal cell carcinoma**, because, in the dataset's words, there is no clinical value in distinguishing them for management or treatment, and they often co-exist in one tumour with overlapping forms. Naming them individually is optional.\n\n**Basosquamous** carcinoma is not a growth pattern but a differentiation: a basal cell carcinoma containing a moderately or severely atypical or frankly malignant squamous component. The term has been used loosely for collision tumours and for the poorly defined metatypical basal cell carcinoma, but there is reasonable evidence that basal cell carcinoma with squamous atypia recurs and metastasises more often, so the UK dataset asks for it to be identified and treats it as high risk. The many other differentiations a basal cell carcinoma can show, pigmented, adenoid, keratotic, clear cell, granular, with eccrine, apocrine, sebaceous or follicular components, need not be recorded at all: they do not change what is done.\n\nIn practice most tumours are composite, containing low-risk and high-risk patterns at once. There is no evidence about what percentage or position of a high-risk pattern matters, so the UK rule is pragmatic: the overall risk status is read from the highest-risk pattern present, irrespective of percentage or location, and once a high-risk component is recorded the low-risk ones need not be.",
    cancers: ["basal-cell-carcinoma", "locally-advanced-bcc", "skin-cancer"],
    terms: ["skin-cancer-high-risk-features", "tnm-skin-carcinoma", "keratinocyte-cancer", "cscc-subtype-and-grade"],
    related: ["histology", "tumour-differentiation", "mohs-surgery", "resection-margins"],
    sections: ["diagnostics"],
    links: [SRC.g123, SRC.crukBcc, SRC.badBcc, SRC.who5, SRC.who4, SRC.who5review, SRC.icdo32],
    notes: [
      "The classification cannot see the distinction the UK cares most about. ICD-O, the morphology coding system registries use, gives micronodular basal cell carcinoma no code of its own: it is a related term sharing 8097/3 with nodular, which is a low-risk pattern. Sclerosing and morphoeic share 8092/3 with infiltrating. So a registry coding from ICD-O alone cannot reliably tell a high-risk micronodular tumour from a low-risk nodular one, which is worth knowing before reading anything derived from registry morphology codes.",
      "Why the pattern is on the report at all when the treatment is an operation either way. Because it decides which operation, where it is done and by whom. The UK dataset is explicit that low-risk basal cell carcinomas can be treated in primary care by appropriately trained and accredited practitioners, and that all others must be treated in secondary care; and that high-risk tumours with involved margins, patients for Mohs surgery and immunocompromised patients go to the skin cancer multidisciplinary team (G123). A morphoeic tumour on a nose and a nodular one on a back are the same diagnosis and a different day.",
      "The one thing a growth pattern is not: a grade. Basal cell carcinoma is not graded. A proposal to divide it into differentiated and undifferentiated types had limited support and was not adopted, and the UK dataset records pattern and, where present, squamous differentiation, and nothing else of that kind (G123). If a report gives a grade for a basal cell carcinoma, it is answering a question the dataset does not ask.",
    ],
  },

  { id: "cscc-subtype-and-grade", kind: "term", asOf, name: "The subtype and grade on a cutaneous squamous cell carcinoma report", category: "Pathology", wikipedia: W("Squamous-cell_carcinoma_of_the_skin"),
    aka: ["acantholytic squamous cell carcinoma", "desmoplastic squamous cell carcinoma", "spindle cell squamous cell carcinoma", "sarcomatoid squamous cell carcinoma", "adenosquamous carcinoma of skin", "basaloid squamous cell carcinoma", "well differentiated squamous cell carcinoma", "moderately differentiated squamous cell carcinoma", "poorly differentiated squamous cell carcinoma", "cSCC grade", "cSCC subtype", "Broders grade", "no special type squamous cell carcinoma", "classic squamous cell carcinoma"],
    tldr: "A squamous cell carcinoma report carries two separate things: a subtype, which is the shape the tumour grows in, and a grade, which is how much it still looks like normal skin. Most are of no special type and well differentiated. Four subtypes and the poorly differentiated grade are counted as high risk in Britain.",
    summary: "**The subtype.** The UK dataset uses a modified WHO classification and recognises that a squamous cell carcinoma may come from surface epidermis or from hair follicle epithelium, either of which can be in situ or invasive and low or high risk (RCPath G124). If none of the named subtype features are present, the tumour is reported as **no special type**, also called classic, and that is what most are. The subtypes national guidelines and NICE treat as clinically high risk are **acantholytic** (cells falling apart from one another, leaving pseudoglandular spaces), **desmoplastic** (defined as having more than 30 percent desmoplastic stroma) and **spindle cell** or sarcomatoid. The dataset notes a real disagreement about spindle cell tumours: the Armed Forces Institute of Pathology accepts spindle cell carcinoma arising after radiotherapy as high risk but regards spindle cell tumours on sun-exposed skin as not carrying the same aggressive potential. **Adenosquamous** carcinoma is high risk to WHO. Invasive squamous cell carcinoma with adjacent Bowen's disease is usually treated as high risk, although there is increasing debate about whether that should be restricted to areas not exposed to ultraviolet light. **Basaloid** squamous cell carcinoma is uncommon in skin, must be told from basal cell carcinoma with immunohistochemistry (BerEP4 and EMA), may arise in pre-existing basaloid Bowen's disease, and is poorly differentiated by definition.\n\n**The grade.** Both UICC and AJCC equate grades 1 to 4 with well, moderately, poorly and undifferentiated, and accept that 3 and 4 can be combined. The UK dataset considered the original Broders method, which scores the percentage of well-differentiated tumour present, and after consultation adopted a three-grade system instead. Well differentiated tumours show easily recognisable and often abundant keratinisation, obvious squamous cells with visible intercellular bridges, minimal pleomorphism and mostly basal mitoses. Moderately differentiated tumours are more disorganised, with more nuclear and cytoplasmic pleomorphism, more and abnormal mitoses, and keratin limited to keratin pearls, horn cysts and scattered single keratinised cells. In poorly differentiated tumours it may be hard to establish the nature of the lesion at all unless intercellular bridges or small foci of keratinisation are found; rarely the tumour is completely anaplastic and keratin immunohistochemistry is needed.\n\nThe grading rule matters and is not obvious. AJCC gives no guidance on what percentage of a differentiated component sets the grade, so the UK dataset follows the widely used approach of classifying a tumour by **its most poorly differentiated region, irrespective of the percentage present**. A tumour that is 95 percent well differentiated with one poorly differentiated focus is a poorly differentiated tumour on a British report. Recording the percentages of each component is optional. Loss of differentiation correlates with clinical risk, which is the whole reason the grade is there.",
    cancers: ["cutaneous-scc", "advanced-cutaneous-scc", "bowens-disease", "skin-cancer"],
    terms: ["skin-cancer-high-risk-features", "tnm-skin-carcinoma", "bwh-staging-cscc", "keratinocyte-cancer", "bcc-growth-pattern", "keratoacanthoma"],
    related: ["tumour-grade", "tumour-differentiation", "squamous-cell-carcinoma", "histology", "perineural-invasion"],
    sections: ["diagnostics"],
    links: [SRC.g124, SRC.crukScc, SRC.badScc, SRC.who5, SRC.who4, SRC.who5review, SRC.icdo32],
    notes: [
      "Two of the UK's high-risk subtypes are not WHO subtypes at all. The fourth edition of the WHO skin classification (2018) listed squamous cell carcinoma with acantholytic, spindle cell, verrucous, adenosquamous and clear cell subtypes, plus a group of other uncommon variants. The fifth edition (2025) lists verrucous, acantholytic, lymphoepithelial, clear cell, spindle cell and squamous cell carcinoma with sarcomatoid differentiation, and made four deliberate changes: adenosquamous carcinoma is no longer a subtype of cutaneous squamous cell carcinoma, because evidence of ductal differentiation supports classifying most of these tumours as squamoid eccrine ductal carcinoma; pseudovascular squamous cell carcinoma is no longer a subtype and is not recommended as a term for acantholytic carcinoma; sarcomatoid differentiation is now the only acknowledged uncommon subtype; and lymphoepithelioma-like is not recommended for lymphoepithelial carcinoma. Desmoplastic squamous cell carcinoma, which the UK singles out as high risk and defines by more than 30 percent desmoplastic stroma, has never had a WHO heading in either edition: it is an AJCC, BAD, NICE and SIGN construct. So is the UK's treatment of adenosquamous carcinoma as a high-risk subtype of this cancer, which the fifth edition has now moved elsewhere. Where a British report and an international reference disagree about what the tumour is called, this is usually why.",
      "Why the report may say 'no special type'. It is not a shrug. The dataset defines it as the default for a surface-epidermal squamous cell carcinoma with none of the high-risk subtype features present, and diagnostic uncertainty about the subtype is entered separately as 'uncertain'. Reading 'no special type' on a report is reading that the pathologist looked for acantholytic, desmoplastic, spindle cell and adenosquamous features and did not find them.",
      "A grade is not a stage and neither is a risk band. The grade says how abnormal the cells look; the stage says how big the tumour is and where it has reached; the risk band is what a clinician or a multidisciplinary team makes of both together plus the site, the immune state and the margins. A well-differentiated 5 cm tumour and a poorly differentiated 5 mm one are the same grade question answered differently and the same stage question answered differently again.",
    ],
  },

  { id: "tnm-skin-carcinoma", kind: "term", asOf, name: "How skin carcinoma is staged in Britain: UICC TNM, and why it is not the American system", category: "Pathology", wikipedia: W("TNM_staging_system"),
    aka: ["TNM skin carcinoma", "UICC TNM 9 skin", "UICC TNM 8 skin", "skin cancer staging", "carcinoma of the skin staging", "skin carcinoma of the head and neck", "AJCC 8 cutaneous squamous cell carcinoma", "pT1 skin", "pT2 skin", "pT3 skin", "pT4a skin", "pT4b skin", "basal cell carcinoma staging", "cSCC staging", "deep invasion skin", "stage 0 skin cancer"],
    tldr: "UK skin carcinoma reports are staged against the UICC's system, not the American AJCC's, and the two are not the same: the American manual covers only the head and neck, while the UICC covers the whole body and includes basal cell carcinoma. In practice almost no basal cell carcinoma is ever given a stage, because the stage would not change anything.",
    summary: "**Which system, and why.** The Royal College of Pathologists assessed both and chose UICC, noting that UICC TNM 'is the version favoured by NCRAS in the UK' and that the decision between the two rested on the staging of non-melanoma skin cancer, because for melanoma and Merkel cell carcinoma the two are now identical (G123). The difference is one of coverage. The AJCC eighth edition has a chapter on cutaneous squamous cell carcinoma of the head and neck, which also takes in basal cell and adnexal carcinoma but not Merkel cell carcinoma, and it has no staging system for squamous cell carcinoma anywhere else on the body. The UICC has both a head-and-neck chapter and a separate carcinoma-of-the-skin chapter for the rest, essentially trunk and limbs but excluding the eyelid, vulva, penis and perianal skin. The boundary between the two regions is the acromioclavicular joint in front and the upper margin of the shoulder blade behind. A further small discrepancy has never been resolved: UICC divides the size categories at 20 mm or less, over 20 to 40 mm and over 40 mm, while AJCC divides at under 20 mm, 20 to under 40 mm and 40 mm or more, and the RCPath judged the UICC breakpoints more likely to be correct because they match the ones both bodies use for Merkel cell carcinoma and lip and oral cavity tumours.\n\n**The categories, in the ninth edition now in force.** pTis is carcinoma in situ. pT1 is 20 mm or less in maximum dimension, pT2 over 20 up to 40 mm, pT3 over 40 mm; pT3 is also reached by minor bone erosion, by perineural invasion or by deep invasion, whatever the size. Deep invasion means invasion beyond the subcutaneous fat, or more than 6 mm measured from the granular layer of adjacent normal epidermis to the base of the tumour. Perineural invasion means tumour within the nerve sheath of a nerve lying deeper than the dermis, or measuring 0.1 mm or more in calibre, or involvement of five or more nerves in a section, short of foramen or skull base involvement. pT4a is gross cortical or marrow invasion and pT4b is axial skeleton invasion including the vertebral foramen and epidural space. Nodal categories differ between the two body regions: for trunk and limbs they run on ipsilateral node size alone, 30 mm and 60 mm, and a contralateral node counts as distant metastasis; for head and neck they are subdivided by extranodal extension as well. The stage groups are simple: stage 0 is Tis, stage I is T1N0, stage II is T2N0, stage III is T3N0 or any of T1 to T3 with N1, stage IV is anything more.\n\n**Why almost nobody is told a stage.** Cancer Research UK puts it plainly: most basal cell carcinomas do not need staging because it is very rare for them to spread, and staging is more likely with a squamous cell carcinoma because those can spread, although that is still rare. So the odd position in Britain is that basal cell carcinoma is formally stageable, with its own UICC appendix in the national reporting dataset, and is almost never staged; while in the United States there is no system for it outside the head and neck at all. Neither country routinely gives a person with a basal cell carcinoma a stage number, and a reader who cannot find one on their letter has not been overlooked.",
    cancers: ["basal-cell-carcinoma", "cutaneous-scc", "bowens-disease", "skin-cancer", "advanced-cutaneous-scc", "locally-advanced-bcc", "merkel-cell-carcinoma"],
    terms: ["bwh-staging-cscc", "skin-cancer-high-risk-features", "cscc-subtype-and-grade", "bcc-growth-pattern", "keratinocyte-cancer"],
    related: ["tnm-staging", "cancer-stage", "ajcc-stage", "perineural-invasion", "extranodal-extension"],
    sections: ["diagnostics"],
    links: [SRC.tnm9skin, SRC.tnm9scc, SRC.g123, SRC.g124, SRC.badTnm8, SRC.crukStages, SRC.ajccV9, SRC.rcpathIndex, SRC.badScc, SRC.badBcc],
    notes: [
      "The British guidelines say the same thing as the pathologists, in their own words. The British Association of Dermatologists' 2020 cutaneous squamous cell carcinoma guideline states that the guideline development group adopted the Royal College of Pathologists dataset, and that this, along with Public Health England, endorses the UICC eighth edition rather than the AJCC eighth edition, noting that AJCC 8 covers only head and neck disease. The 2021 basal cell carcinoma guideline says it adapted the American NCCN criteria 'to equate to the UICC8 and RCPath dataset' because the UICC version 'has been endorsed for use in the UK'. Both also note that the eyelid has been excluded from skin carcinoma staging for several editions and has a staging system of its own.",
      "The American system has not been revised for skin, which is why the comparison is still with the eighth edition. The AJCC is issuing its ninth edition site by site rather than as a book, and states that all disease sites in the eighth edition remain current until replaced. Cervix, appendix, anus, brain and spinal cord, seven neuroendocrine and gynaecological sites, lung, thymus, pleural mesothelioma, nasopharynx, salivary glands and HPV-associated oropharynx have been released; cutaneous carcinoma has not. So an American source citing AJCC 8 for skin in 2026 is citing the current American system, while a British report citing UICC TNM 9 is citing a newer one.",
      "What the eighth edition changed, and why it mattered here more than elsewhere. The joint review by the British Association of Dermatologists and the Royal College of Pathologists set it out: the T1 to T3 categories for non-melanoma skin cancer were redefined around new 20 mm and 40 mm divisions, and new risk factors can upstage T1 or T2 to T3. That review states that Public Health England and the Royal College of Pathologists adopted UICC TNM 8 for skin cancer staging, and warns that the change would affect the management and commissioning of both melanoma and non-melanoma skin cancer (Keohane 2018). Before it, in the seventh edition, most squamous cell carcinomas fell into T2 and T3 and T4 cases were rare, which is the problem the next term is about.",
      "What the ninth edition changed. The perineural invasion definition now includes involvement of five or more nerves in a section alongside the nerve-calibre and nerve-depth criteria, and UICC states that pT is identical to T. The UK appendix carrying the ninth edition for skin carcinoma is dated 6 November 2025 and combines the head-and-neck and carcinoma-of-the-skin chapters into one table, covering basal cell, squamous cell and adnexal carcinoma but excluding Merkel cell carcinoma and carcinomas of the eyelid, vulva, penis, non-hair-bearing lip and non-hair-bearing perianal skin.",
      "The size on the report may be a clinical measurement rather than a microscopic one. Both bodies prefer the clinical maximum dimension and allow a pathological one if no clinical measurement is available, and the UK dataset added an item recording which was used. This is worth knowing because it means a difference of a millimetre either side of 20 mm can be a difference of measuring technique rather than of tumour.",
    ],
  },

  { id: "bwh-staging-cscc", kind: "term", asOf, name: "The Brigham and Women's Hospital staging system, and why squamous cell carcinoma has two", category: "Pathology", wikipedia: W("Squamous-cell_carcinoma_of_the_skin"),
    aka: ["BWH staging", "Brigham and Women's Hospital staging", "BWH T stage", "BWH T2b", "BWH T2a", "BWH T3", "alternative tumour staging cSCC", "cSCC risk stratification", "Baum risk bands"],
    tldr: "The anatomical staging systems put almost every squamous cell carcinoma in one or two categories, so they cannot pick out the few that will spread. A Boston group built an alternative that counts four risk factors instead of measuring the tumour, and it finds the same poor outcomes in a group half the size. Britain uses the anatomical system and treats the Boston one as evidence, not policy.",
    summary: "**The problem it was built for.** In a cohort of 256 primary high-risk squamous cell carcinomas, outcomes for AJCC stages T2 to T4 were statistically indistinguishable, because fewer than 2 percent of the cohort reached T3 or T4, which then required bone invasion. The result was that 83 percent of nodal metastases and 92 percent of deaths happened in stage T2 (Jambusaria-Pahlajani 2013). A stage that contains almost everyone and almost every bad outcome cannot be used to decide who needs extra treatment.\n\n**How it works.** The alternative counts four independent risk factors: poor differentiation, perineural invasion, tumour diameter of 2 cm or more, and invasion beyond the subcutaneous fat. No factors is T1, one factor is T2a, two or three factors is T2b, and four factors or bone invasion is T3. In the derivation cohort T2b tumours were only 19 percent of cases but accounted for 72 percent of nodal metastases and 83 percent of deaths from the disease.\n\n**How it holds up.** In 1,818 primary tumours from 2000 to 2009, AJCC and UICC T3 and T4 were indistinct, with overlapping confidence intervals, and were very rare, 0.3 percent and 3 percent of the cohort respectively; most poor outcomes fell in the low stages, 86 percent for AJCC and 70 percent for UICC. Under the Boston system only 5 percent of tumours were high stage, T2b or T3, and they carried 60 percent of poor outcomes, 70 percent of nodal metastases and 83 percent of disease-specific deaths. Ten-year cumulative incidences in low-stage tumours were 1.4 percent local recurrence, 0.6 percent nodal metastasis and 0.2 percent death from the cancer; in high-stage tumours, 24 percent, 24 percent and 16 percent (Karia 2014). Against the eighth edition, which was a real improvement on the seventh, the comparison is closer but the same in shape: AJCC 8 T3 and T4 were 18 percent of 680 head and neck tumours and the Boston T2b and T3 were 9 percent, and both captured about 71 percent of metastases and 85 to 92 percent of deaths; the Boston system had higher specificity, 93 percent, and higher positive predictive value, 30 percent, and better C statistics for nodal metastasis and disease-specific death, with no difference for local recurrence or overall survival (Ruiz 2019). The authors' conclusion was that AJCC 8's failure to separate T2 from T3 leaves a 23 percent group at significant risk, too large for routine nodal staging or adjuvant treatment.\n\n**Where Britain stands.** UK reports stage against UICC (see `tnm-skin-carcinoma`) and stratify risk separately, and the Royal College of Pathologists has taken an explicit and dissenting position on the risk bands built on the Boston system. It sets out its own numerical thresholds: an adverse consequence rate, counting recurrence, nodal spread, systemic spread or death, below 5 percent is low risk, 5 to 20 percent is high risk and over 20 percent is very high risk; and any squamous cell carcinoma under 20 mm across or under 2 mm thick with no additional factors is, in its words, of negligible rather than merely low risk. A proposal derived from the Boston system calls 5 to 20 percent intermediate and over 20 percent high. The RCPath judges that restricting the word high risk to over 20 percent is inappropriate, that those intermediate cases are better called high risk and the high-risk ones very high risk, and that the proposal 'could potentially leave some serious intermediate cases under-rated in terms of risk and thereby receive inappropriate clinical management' (G124). Its final position is that risk stratification is better done by the treating clinician or the skin cancer multidisciplinary team than recorded as a core item in a pathology report at all.",
    cancers: ["cutaneous-scc", "advanced-cutaneous-scc", "skin-cancer"],
    terms: ["tnm-skin-carcinoma", "skin-cancer-high-risk-features", "cscc-subtype-and-grade"],
    related: ["cancer-stage", "tnm-staging", "perineural-invasion", "prognosis"],
    sections: ["diagnostics"],
    links: [SRC.bwh2013, SRC.bwh2014, SRC.ajcc8v7, SRC.bwhVsAjcc8, SRC.g124],
    notes: [
      "Why two systems is the honest answer rather than a failure. They are answering different questions. An anatomical stage is built to be recorded by every registry in the world from a measurement anybody can take, and to be comparable across decades and countries. A risk classification is built to decide what to do about one tumour in front of one person this week. The first cannot be abandoned without losing every trend line; the second cannot be abandoned without treating the wrong people. Any source presenting one of them as the correct staging of squamous cell carcinoma is answering only half the question.",
      "All these numbers come from one hospital. The derivation and both validations are cohorts from a single academic centre in Boston, referred there because their tumours were difficult, and the papers themselves call for population-based validation. Rates of metastasis and death in an unselected population are lower than in any of these cohorts. What transfers is the ranking, which tumours are dangerous, rather than the absolute percentages.",
    ],
  },

  { id: "skin-cancer-high-risk-features", kind: "term", asOf, name: "What makes a skin cancer high risk: the UK feature lists", category: "Pathology", wikipedia: W("Skin_cancer"),
    aka: ["high-risk basal cell carcinoma", "high-risk squamous cell carcinoma", "high-risk skin cancer", "low-risk skin cancer", "skin cancer risk stratification", "high-risk pathological features", "skin cancer MDT referral", "involved margin skin cancer", "close margin skin cancer"],
    tldr: "Low risk and high risk are the words that actually decide what happens to a keratinocyte cancer in Britain, more than any stage. One high-risk feature is enough. The lists are short, they are about the tumour and the margin, and a clinician can add clinical features the pathologist cannot see.",
    summary: "The UK reporting datasets publish two tables of high-risk pathological features, and in both, any one feature is enough for high-risk status (RCPath G123 and G124).\n\n**Basal cell carcinoma.** Growth pattern: infiltrative, meaning infiltrating, sclerosing or micronodular. Differentiation: basosquamous. Level of invasion: beyond the subcutaneous fat. Depth or thickness: more than 6 mm. Perineural invasion present. Lymphovascular invasion present, for basosquamous tumours. TNM T category T2, T3 or T4. And margins: involved at 0 mm, or not involved but under 1 mm.\n\n**Squamous cell carcinoma.** Subtype: desmoplastic, spindle cell or sarcomatoid, acantholytic or adenosquamous. Grade: poorly differentiated. Perineural invasion present. Lymphovascular invasion present. Thickness over 4 mm. Level of invasion reaching the subcutaneous fat or beyond. TNM pathological stage T2, T3 or T4. And the same margin rule. The dataset records which body named each feature, which is a useful map of where the guidelines disagree: NICE and the British Association of Dermatologists agree on perineural invasion, thickness over 4 mm and involvement of fat; the BAD's own text and table disagree with each other about whether moderately differentiated tumours count, with the table and the NCCN including them and the text, AJCC, SIGN and WHO restricting it to poorly differentiated; the RCPath follows poorly differentiated.\n\nTwo things about these lists are easy to miss. First, they are pathological only. The dataset says in terms that a low-risk squamous cell carcinoma on histological criteria may be upgraded to overall high risk once clinical features are added by the clinician or the multidisciplinary team, and the same note appears on the basal cell table. Site, previous radiotherapy, recurrence, immunosuppression and how fast the lesion grew are not on the pathologist's slide. Second, the whole approach is contested from inside. Both datasets conclude that risk stratification is better undertaken by the treating clinician and the skin cancer multidisciplinary team than as a core entry in a histopathology report, partly because the joint RCPath and BAD national audit found that risk status was one of the most frequently omitted core items in skin cancer reports.\n\nThe consequence a patient meets is the referral rule. Low-risk basal cell carcinomas can be treated in primary care by appropriately trained and accredited practitioners; everything else goes to secondary care. High-risk basal cell carcinomas with involved margins, patients for Mohs surgery and immunocompromised patients go to the local skin cancer multidisciplinary team; metastatic disease and people with a genetic susceptibility go to the specialist team.",
    cancers: ["basal-cell-carcinoma", "cutaneous-scc", "locally-advanced-bcc", "advanced-cutaneous-scc", "skin-cancer", "bowens-disease"],
    terms: ["bcc-growth-pattern", "cscc-subtype-and-grade", "tnm-skin-carcinoma", "bwh-staging-cscc"],
    related: ["resection-margins", "perineural-invasion", "mohs-surgery", "multidisciplinary-tumour-board", "wide-local-excision"],
    sections: ["diagnostics"],
    links: [SRC.g123, SRC.g124, SRC.badBcc, SRC.badScc, SRC.rcpathIndex],
    notes: [
      "The same feature has two different thresholds depending on what it is being used for, and the UK dataset publishes a table comparing them. For squamous cell carcinoma, thickness over 4 mm makes a tumour high risk for clinical and multidisciplinary team management, while it takes over 6 mm to upstage a T1 or T2 to T3 in the staging system; level of invasion is 'at or beyond the subcutaneous fat' for risk and 'beyond the subcutaneous fat' for staging; and grade, lymphovascular invasion, subtype and margin status count for risk and not at all for staging (RCPath G124, appendix F). The dataset gives this mismatch as one of the reasons risk status caused confusion in practice, noting that 'particular confusion was generated by different risk factors being used for TNM upstaging compared with the tumour itself'. A tumour can therefore be high risk and low stage at the same time without either label being wrong.",
      "Risk status used to be a core item in the UK report and was removed. The dataset records that the core item 'caused numerous practical and clinical difficulties, reflected in the low level of acceptance and usage identified in the joint BAD-RCPath audit on NMSC', that binary low and high risk 'at times oversimplified a more complex clinicopathological situation', and that it was therefore moved out of the core section. What replaced it is a judgement made by the treating clinician or the skin cancer multidisciplinary team with the clinical facts in front of them. So an absent risk label on a report is the system working as designed, not an omission.",
      "The British Association of Dermatologists adds the things a slide cannot show. Its 2021 basal cell carcinoma guideline stratifies low against high risk on twelve criteria, of which only about half are pathological: alongside growth pattern, basosquamous differentiation, level of invasion, depth, perineural invasion, pathological T stage and margins, it counts the anatomical area and size together, whether the borders are well or poorly defined, whether the tumour is primary or recurrent, whether the person is immunosuppressed, and whether the site has had radiotherapy before. Its anatomical areas run from area L, the trunk and limbs, through area M, including the cheeks, forehead, scalp and neck, to area H, the mask areas of the face together with the hands, feet, ankles and genitals, where a tumour of any size is high risk. That is why the same 8 mm tumour is low risk on a back and high risk on a nose.",
      "The margin rule is stricter than most people expect, and it is not the same as an involved margin. A margin that is clear but under 1 millimetre is itself a defined high-risk pathological feature in both datasets. NICE and the national quality surveillance programme do not make a clear margin under 1 mm a mandatory reason for multidisciplinary team referral, and the datasets say the decision is individual or locally agreed, with a low threshold for asking the team. So a letter saying the cancer was completely removed and the case is still going to the team is not a contradiction.",
      "Counting the features matters as well as having one. The squamous dataset notes that the evidence strongly suggests that the number of high-risk factors present has significant clinical importance, and the greater the number the greater the overall risk. That is the same insight the Brigham and Women's Hospital system is built on, arriving at the same conclusion from the other direction.",
    ],
  },

  { id: "actinic-keratosis", kind: "term", asOf, name: "Actinic keratosis (solar keratosis): sun damage, not cancer", category: "Pathology", wikipedia: W("Actinic_keratosis"),
    aka: ["actinic keratosis", "actinic keratoses", "solar keratosis", "solar keratoses", "AK", "sun spots", "sunspots", "pre-cancerous skin patches", "L57.0"],
    tldr: "Rough, scaly patches on skin that has had a lot of sun, commonest on the scalp, face, ears, forearms and backs of hands. They are not cancer and are not counted as cancer anywhere in the UK, but they mark skin that has been damaged enough to be worth watching, and a small proportion go on to become squamous cell carcinoma.",
    summary: "An actinic keratosis is a patch of keratinocytes that have accumulated ultraviolet damage. Two coding systems agree about what it is not. In ICD-10 it is L57.0, inside the chapter on diseases of the skin and subcutaneous tissue, in the block for skin changes due to chronic exposure to nonionizing radiation; that is not a neoplasm code, and the neoplasm chapter, where skin cancer lives as C44 and carcinoma in situ of skin as D04, is a different chapter of the same book. In ICD-O, the morphology system registries use, it is 8070/0, where the final digit means benign, and the classification pointedly did not give it 8070/2, the code that exists and means squamous cell carcinoma in situ. Both the fourth and the fifth editions of the WHO skin classification file it under carcinoma precursors rather than under carcinomas. No UK cancer registry registers actinic keratoses as cancer. That is why they are a glossary entry here and not a cancer page, and it is worth being explicit about, because being told you have a pre-cancer is frightening out of proportion to what it means.\n\nHow often one becomes a cancer is a question the literature answers carefully rather than confidently. In the largest prospective study, 7,784 actinic keratoses on the faces and ears of 169 participants in a chemoprevention trial were followed, and the risk of one progressing to a primary squamous cell carcinoma, invasive or in situ, was 0.60 percent at 1 year and 2.57 percent at 4 years; 55 percent of the lesions had disappeared by the 1-year follow-up and 70 percent by 5 years (Criscione 2009). The classic Australian study of 21,905 solar keratoses put the risk of one transforming within a year at less than 1 in 1,000 (Marks 1988). A systematic review found published rates from 0 to 0.075 percent per lesion-year, up to 0.53 percent per lesion in people with a previous skin cancer, regression rates for single lesions of 15 to 63 percent after a year, and concluded that 'currently, no reliable estimates concerning the frequency of AK developing into invasive carcinoma can be given' (Werner 2013). The British guideline quotes both the under 1 in 1,000 per annum figure and a modelled probability of about 10 percent of developing a squamous cell carcinoma within ten years for a person with an average of 7.7 lesions (de Berker 2017).\n\nThe reason those two framings differ is the reason the lesions matter at all. Per lesion the risk is tiny; per person with many lesions it is not, and the same study that found a low per-lesion risk also found that about 65 percent of all the squamous cell carcinomas and 36 percent of the basal cell carcinomas diagnosed in the cohort arose where an actinic keratosis had previously been seen (Criscione 2009). So an individual patch is very unlikely to be the one, and the skin that grows them is where the cancer will come from.\n\nWhat they do mean is that the skin around them is damaged too. Actinic keratoses usually come in numbers rather than singly, and the useful way to think about them is as visible marks in a wider field of sun-damaged skin, the phenomenon called field cancerisation. That is why treatment is often aimed at an area rather than at a spot, and why having many of them raises the chance of a squamous cell carcinoma somewhere in that area rather than at any particular lesion. The European consensus that adopted the term keratinocyte cancer includes actinic keratosis in the group as a keratinocyte-derived precursor, which is an accurate description of where it sits: on the same biological road as squamous cell carcinoma, a long way from the end of it.\n\nWhere actinic keratosis sits relative to the two pages beside it is worth stating plainly. Actinic keratosis is dysplasia in sun-damaged skin and is not registered as cancer. Bowen's disease is squamous cell carcinoma in situ, a carcinoma confined to the epidermis, and has its own page here. Invasive cutaneous squamous cell carcinoma has broken through into the dermis. The three are a sequence in principle and not a timetable in practice: most actinic keratoses never become anything, and most Bowen's disease never becomes invasive.",
    cancers: ["cutaneous-scc", "bowens-disease", "skin-cancer", "basal-cell-carcinoma"],
    terms: ["keratinocyte-cancer", "keratoacanthoma", "keratinocyte-cancer-counting", "cscc-subtype-and-grade"],
    related: ["field-cancerisation", "dysplasia", "carcinoma-in-situ", "in-situ"],
    sections: ["diagnostics", "prevention"],
    links: [SRC.icd10, SRC.icdo32, SRC.kcConsensus, SRC.crukTypes, SRC.crukScc, SRC.criscione2009, SRC.werner2013, SRC.badAk, SRC.who5, SRC.who4],
    notes: [
      "Why a page was considered and not written. The corpus's rule is that a cancer record is a tumour entity (docs/CANCER-PAGES.md). Actinic keratosis fails it on the two clearest available tests: it is coded 8070/0, benign, in ICD-O, and L57.0, outside the neoplasm chapter, in ICD-10, and it is registered as cancer by no UK registry. The corpus does give pages to in-situ carcinomas that carry a /2 behaviour code and are registered, which is why Bowen's disease has one and this does not. The line is the behaviour code rather than anybody's judgement of severity, which is what makes it possible to apply the same line to the next case, and what made it survive the WHO fifth edition's rearrangement of this same group of lesions.",
      "Where the boundary with Bowen's disease actually sits, under the microscope. The British guideline describes it precisely: the dysplasia in an actinic keratosis 'may be restricted to the basal layer or may extend to full-thickness atypia', and at the point where it is full thickness 'the lesion is known as SCC in situ (Bowen disease)' (de Berker 2017). So the difference between the thing on this page and the thing on the next one is how far up the epidermis the abnormal cells reach, which is a continuum being cut at a line, and part of why the argument about whether an actinic keratosis is already a cancer has run for decades.",
      "The number of lesions is the thing that changes management, and it is not counted in any national statistic. Because actinic keratoses are not registered, there is no national figure for how many people have them, and the burden they place on dermatology and general practice is invisible in the cancer statistics in exactly the way the keratinocyte cancers themselves are only partly visible (see `keratinocyte-cancer-counting`).",
    ],
  },

  { id: "keratoacanthoma", kind: "term", asOf, name: "Keratoacanthoma: the tumour that may be a squamous cell carcinoma", category: "Pathology", wikipedia: W("Keratoacanthoma"),
    aka: ["keratoacanthoma", "KA", "squamous cell carcinoma keratoacanthoma type", "keratoacanthomatous squamous cell carcinoma", "self-healing squamous carcinoma"],
    tldr: "A dome-shaped lump with a central plug of keratin that grows fast over a few weeks and may then shrink on its own. Whether it is a benign tumour or a squamous cell carcinoma that happens to regress has been argued for decades; the WHO treats it as a type of squamous cell carcinoma, and no single test tells them apart.",
    summary: "No question in skin pathology has been reopened as often. The fourth edition of the WHO skin classification (2018) placed keratoacanthoma inside the squamous cell carcinoma section, and the UK reporting dataset recorded that position in terms: it notes the WHO terminology, which considers keratoacanthoma as synonymous with invasive squamous cell carcinoma of keratoacanthomatous type; it notes that there is still considerable national and international debate as to whether keratoacanthoma is truly a pathologically benign or malignant neoplasm; and it records that, to date, no one single criterion can make a reliable distinction between squamous cell carcinoma and keratoacanthoma, so each case must be approached using a constellation of clinical and pathological features, including a history of an initial period of rapid growth (RCPath G124). The fifth edition (2025) then moved it back out, making it a heading of its own beside the basal cell and squamous cell carcinomas, while conceding the same difficulty: reliable distinction between the two is not always possible, immunohistochemistry for p53, Ki-67 and p16 helps in many cases, and where it does not, the uncertainty can be reported as a squamoproliferative tumour of uncertain malignant potential.\n\nThe coding follows the confusion rather than resolving it. ICD-O-3.2 carries keratoacanthoma as a related term under 8071/3, squamous cell carcinoma, keratinizing, which is a malignant behaviour code. The UK dataset's own coding appendix does the opposite, coding keratoacanthoma as SNOMED M7286/0, a benign behaviour code, and keeping keratoacanthoma-like squamous cell carcinoma separately at M8071/3. A British pathologist reporting the same lesion under the two systems would file it as benign in one and malignant in the other.\n\nThe same dataset adds a safety rule that is the practical point for a reader. The term keratoacanthoma should perhaps be avoided in an immunosuppressed patient, and for large lesions, and in a subungual location under a nail, because all of those are considered to have greater potential for aggressive behaviour. In other words, the cases where calling it a keratoacanthoma would be most reassuring are the cases where it is least safe to.\n\nThis is why keratoacanthoma is a word here and not a page. The corpus gives a page to a lesion with a settled behaviour that registries register; this one has neither, and its position in the reference classification has moved in both directions within seven years. Anyone whose biopsy report carries the word should read the cutaneous squamous cell carcinoma page, which is where the management of the thing in front of them is written.",
    cancers: ["cutaneous-scc", "skin-cancer", "bowens-disease"],
    terms: ["cscc-subtype-and-grade", "keratinocyte-cancer", "actinic-keratosis"],
    related: ["squamous-cell-carcinoma", "histology", "tumour-differentiation"],
    sections: ["diagnostics"],
    links: [SRC.g124, SRC.crukScc, SRC.who5, SRC.who4, SRC.who5review, SRC.icdo32],
    notes: [
      "Why spontaneous regression is not a reason to wait. The natural history that gave keratoacanthoma its reputation, rapid growth then involution, is exactly what makes it indistinguishable in advance from a squamous cell carcinoma that will not involute. Since no single criterion separates them and the diagnosis is made on the whole picture rather than one feature, the safe path is to treat the lesion and let the pathology decide afterwards.",
    ],
  },

  { id: "inherited-skin-cancer-syndromes", kind: "term", asOf, name: "Inherited syndromes that cause skin cancer: Gorlin syndrome and xeroderma pigmentosum", category: "Genomics & genetics", wikipedia: W("Nevoid_basal_cell_carcinoma_syndrome"),
    aka: ["Gorlin syndrome", "Gorlin-Goltz syndrome", "naevoid basal cell carcinoma syndrome", "nevoid basal cell carcinoma syndrome", "NBCCS", "BCNS", "basal cell naevus syndrome", "PTCH1", "SUFU", "xeroderma pigmentosum", "XP", "inherited skin cancer syndrome", "genetic skin cancer syndrome"],
    tldr: "Two rare inherited conditions cause skin cancer decades earlier and in far greater numbers than sun exposure alone. Gorlin syndrome causes many basal cell carcinomas from a young age through a fault in the same pathway the hedgehog inhibitor drugs block. Xeroderma pigmentosum leaves cells unable to repair ultraviolet damage at all.",
    summary: "**Gorlin syndrome**, also called naevoid basal cell carcinoma syndrome, is autosomal dominant and is caused in most cases by a germline variant in PTCH1, the gene whose loss also drives ordinary sporadic basal cell carcinoma. In the Manchester series of people meeting the clinical criteria, 134 of 193 (69.4 percent) had an identifiable germline PTCH1 variant, 11 (5.7 percent) had a SUFU variant, and 48 (24.9 percent) had none found; no PTCH2 variant was identified, and the authors judged that gene probably rarely involved (Foulkes 2021). Birth incidence in a UK family genetic register service was estimated at 1 in 14,963 and prevalence at 1 in 30,827, with 26 percent of cases arising from a new mutation rather than an affected parent (Evans 2010). In a population-based UK study of 84 cases, basal cell carcinomas and jaw cysts each occurred in over 90 percent of patients by the age of 40 and both could appear before the age of 10; ovarian calcification or fibroma occurred in 24 percent, medulloblastoma in 5 percent, cardiac fibroma in 3 percent, cleft palate in 5 percent, and ophthalmic abnormalities such as squint or cataract in 26 percent (Evans 1993). The features are less prominent in people with a SUFU variant, and many of them never meet the clinical criteria at all (Foulkes 2021). The syndrome is the reason the hedgehog pathway was identified as the driver of basal cell carcinoma, and therefore the reason the hedgehog inhibitor drugs exist.\n\n**Xeroderma pigmentosum** is autosomal recessive and rarer, and it is a different kind of problem: the cell cannot repair the damage ultraviolet light does to its DNA. Eight complementation groups are defined by variants in eight genes, XPA, ERCC3, XPC, ERCC2, DDB2, ERCC4, ERCC5 and POLH. Estimated incidence varies from about 1 in 20,000 in Japan to about 1 in 250,000 in the United States and about 2.3 per million live births in western Europe. The consequence is extreme: people with xeroderma pigmentosum have been estimated to carry a 10,000-fold increased risk of non-melanoma skin cancer and a 2,000-fold increased risk of melanoma under the age of 20, and about a 50-fold increase in cancers inside the body, especially of the central nervous system (Lehmann 2011). Many of the complementation groups also cause progressive neurological disease. The UK has a national xeroderma pigmentosum service, at St Thomas' Hospital in London, covering the whole population.\n\nBoth syndromes have their own chapter in the WHO skin classification, under inherited or genetic tumour syndromes associated with skin malignancies, in both the fourth and the fifth editions. Neither is a cancer record here: they are conditions that cause cancers, and the cancers they cause have their own pages.",
    cancers: ["basal-cell-carcinoma", "cutaneous-scc", "skin-cancer", "melanoma", "locally-advanced-bcc", "bowens-disease"],
    terms: ["bcc-growth-pattern", "keratinocyte-cancer", "actinic-keratosis", "skin-cancer-high-risk-features"],
    related: ["germline-testing", "field-cancerisation", "hereditary-cancer-syndromes"],
    sections: ["diagnostics", "prevention"],
    links: [SRC.foulkes2021, SRC.evans2010, SRC.evans1993, SRC.lehmann2011, SRC.who5, SRC.who4],
    notes: [
      "Why a rare syndrome mattered to everybody with this cancer. Identifying PTCH1 as the Gorlin syndrome gene tied basal cell carcinoma to the hedgehog developmental pathway, and the drugs that block that pathway, vismodegib and sonidegib, followed from it. It is one of the clearest cases in oncology of a rare inherited condition explaining the common sporadic disease, and it is why a person with an advanced basal cell carcinoma today has a tablet to take.",
      "Immunosuppression and genetic susceptibility change the referral route as well as the risk. The UK reporting dataset lists immunocompromised patients among those whose basal cell carcinoma requires local skin cancer multidisciplinary team referral, and people with a genetic susceptibility among those requiring specialist team referral, whatever the tumour looks like (RCPath G123).",
    ],
  },
];

